def minWindow(s1: str, s2: str) -> str:
    m, n = len(s1), len(s2)
    min_len = float('inf')
    start = -1

    i = 0
    while i < m:
        if s1[i] == s2[0]:
            j = 0
            k = i
            # Forward pass: try to match entire s2 as subsequence
            while k < m and j < n:
                if s1[k] == s2[j]:
                    j += 1
                k += 1

            if j == n:
                # s2 matched; now move backward to minimize window
                end = k - 1
                j -= 1
                k -= 1
                while j >= 0:
                    if s1[k] == s2[j]:
                        j -= 1
                    k -= 1
                k += 1  # leftmost start
                if end - k + 1 < min_len:
                    min_len = end - k + 1
                    start = k
            i = i + 1
        else:
            i += 1

    if start == -1:
        return ""
    return s1[start:start + min_len]
